import React, { useCallback, useEffect, useRef, useState } from "react";
import { useHistory } from "react-router-dom";
import lottie from "lottie-web";
import { AGENTS } from "./LilAgents";
import { createWalkStates, stepWalk } from "./agentWalkEngine";
import coolMan from "./Cool Man.json";
import femaleWalk from "./Female Character Walking.json";
import "./LilAgentsLottie.css";

// Lottie variant — real authored walk cycles rather than shapes assembled in
// code. The clips only animate the gait; position, turning, resting and
// spacing still come from the shared walk engine.
//
// lottie-web is driven directly instead of via lottie-react so the playhead
// can be scrubbed per frame without pushing React state.

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// Ground covered by one full loop of the clip. This is the knob that stops the
// feet sliding: the playhead is scrubbed from distance travelled, so if the
// character appears to over- or under-step, change this rather than the speed.
const LOOP_DISTANCE = 0.085; // track fractions per clip loop

// On-screen height of the figure itself, ignoring whatever empty padding the
// clip was exported with.
const CHAR_HEIGHT = 172;

// The two clips frame their characters completely differently inside the same
// 1080x1080 canvas, so instead of hard-coding a crop we scrub the loop, union
// the drawn bounds, and retarget the SVG viewBox onto that. Anchored to the
// bottom so the feet land on the tiles whatever the export looked like.
function fitToContent(anim, container) {
  const svg = container.querySelector("svg");
  if (!svg) return;

  // getBBox() on the root <g> reports the clip region for precomp-based clips
  // rather than the drawn content, so measure the union of every painted
  // element's screen rect instead and convert back into viewBox units. That is
  // transform-safe and works whatever the export's structure.
  const svgRect = svg.getBoundingClientRect();
  if (!svgRect.width || !svgRect.height) return;
  const vb = svg.viewBox.baseVal;
  const sx = vb.width / svgRect.width;
  const sy = vb.height / svgRect.height;

  let l = Infinity;
  let t = Infinity;
  let r = -Infinity;
  let b = -Infinity;
  const samples = 12;
  const lastFrame = Math.max(anim.totalFrames - 1, 1);
  const painted = "path,rect,circle,ellipse,polygon,polyline,image";

  for (let i = 0; i < samples; i++) {
    anim.goToAndStop((i / samples) * lastFrame, true);
    svg.querySelectorAll(painted).forEach((el) => {
      const er = el.getBoundingClientRect();
      if (!er.width || !er.height) return;
      l = Math.min(l, er.left);
      t = Math.min(t, er.top);
      r = Math.max(r, er.right);
      b = Math.max(b, er.bottom);
    });
  }
  if (!isFinite(l) || r <= l || b <= t) return;

  const x0 = vb.x + (l - svgRect.left) * sx;
  const y0 = vb.y + (t - svgRect.top) * sy;
  const w = (r - l) * sx;
  const h = (b - t) * sy;
  const pad = h * 0.02;

  svg.setAttribute(
    "viewBox",
    `${x0 - pad} ${y0 - pad} ${w + pad * 2} ${h + pad * 2}`
  );
  svg.setAttribute("preserveAspectRatio", "xMidYMax meet");

  container.style.height = `${CHAR_HEIGHT}px`;
  container.style.width = `${Math.round(CHAR_HEIGHT * (w / h))}px`;
  anim.goToAndStop(0, true);
}

// `faces` is the direction the artwork already points, so the flip can be
// corrected per clip: 1 = drawn walking right, -1 = drawn walking left,
// 0 = front-facing (a flip would be meaningless).
//
// These two exports don't match: Cool Man strides toward the viewer while the
// female clip is a left-facing side view. A front-view walk can't read as
// travelling sideways, so he'll always look like he's walking at the camera.
// Matching side-view clips would fix that; it isn't something code can.
const CLIPS = [
  { data: coolMan, key: "man", faces: 0 },
  { data: femaleWalk, key: "female", faces: -1 },
];

const WALK_OPTS = {
  speed: 0.055,
  minSep: 0.22,
  walkSpan: [0.14, 0.34],
  // Short rests: the clips are walk cycles with no idle pose, so long pauses
  // just leave a frozen character standing there.
  pause: [1.4, 3.6],
};

function LilAgentsLottie() {
  const perchRef = useRef(null);
  const hostRefs = useRef([]); // wrapper divs, positioned by the engine
  const mountRefs = useRef([]); // lottie containers
  const animsRef = useRef([]);
  const [openId, setOpenId] = useState(null);
  const [bubble, setBubble] = useState(null);
  const frozen = prefersReducedMotion();
  const history = useHistory();

  const statesRef = useRef(createWalkStates(AGENTS.length, WALK_OPTS));
  const states = statesRef.current;

  const openIdRef = useRef(null);
  useEffect(() => {
    openIdRef.current = openId;
  }, [openId]);

  // Load the clips once, autoplay off — the frame is set by hand each tick
  useEffect(() => {
    const anims = mountRefs.current.map((container, i) => {
      if (!container) return null;
      return lottie.loadAnimation({
        container,
        renderer: "svg",
        loop: true,
        autoplay: false,
        animationData: CLIPS[i % CLIPS.length].data,
        rendererSettings: { preserveAspectRatio: "xMidYMid meet" },
      });
    });
    animsRef.current = anims;
    anims.forEach((a, i) => {
      if (!a) return;
      const fit = () => fitToContent(a, mountRefs.current[i]);
      if (a.isLoaded) fit();
      else a.addEventListener("DOMLoaded", fit);
    });
    return () => anims.forEach((a) => a && a.destroy());
  }, []);

  useEffect(() => {
    let raf;
    let last = performance.now();
    const start = last;

    const frame = (now) => {
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;
      const time = (now - start) / 1000;

      states.forEach((st, i) => {
        const host = hostRefs.current[i];
        if (!host) return;

        st.frozenByUi = frozen || openIdRef.current === AGENTS[i].id;
        stepWalk(st, states, time, dt, WALK_OPTS);

        host.style.left = `${st.pos * 100}%`;
        const faces = CLIPS[i % CLIPS.length].faces;
        host.style.setProperty("--flip", faces === 0 ? 1 : st.facing * faces);

        // Scrub the clip by distance covered, not by wall clock. The legs then
        // physically cannot outrun the ground, and they stop dead when the
        // character does instead of marching on the spot.
        const anim = animsRef.current[i];
        if (anim && anim.totalFrames) {
          if (st.walking) {
            const loops = st.travelled / LOOP_DISTANCE;
            st.clipPhase = ((loops % 1) + 1) % 1;
          } else if (st.clipPhase > 0.002) {
            // Play out the rest of the cycle instead of freezing mid-stride,
            // then settle on frame 0. These clips have no idle pose, so a hard
            // stop leaves the character stranded mid-step.
            st.clipPhase += dt * 0.8;
            if (st.clipPhase >= 1) st.clipPhase = 0;
          }
          anim.goToAndStop((st.clipPhase || 0) * (anim.totalFrames - 1), true);
        }
      });

      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [frozen, states]);

  // Thought bubbles, same cadence as the other variants
  useEffect(() => {
    if (frozen) return;
    let i = 0;
    const tick = () => {
      const agent = AGENTS[i % AGENTS.length];
      setBubble({
        agentId: agent.id,
        text: agent.phrases[Math.floor(Math.random() * agent.phrases.length)],
      });
      i += 1;
      window.setTimeout(() => setBubble(null), 3200);
    };
    const id = window.setInterval(tick, 6500);
    const first = window.setTimeout(tick, 2200);
    return () => {
      window.clearInterval(id);
      window.clearTimeout(first);
    };
  }, [frozen]);

  const toggle = useCallback(
    (id) => setOpenId((cur) => (cur === id ? null : id)),
    []
  );

  useEffect(() => {
    if (!openId) return;
    const onKey = (e) => e.key === "Escape" && setOpenId(null);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [openId]);

  return (
    <div className="pj-agents-perch-lottie" ref={perchRef}>
      {AGENTS.map((agent, i) => (
        <div
          key={agent.id}
          className="lilottie-agent"
          ref={(el) => (hostRefs.current[i] = el)}
          style={{ left: `${states[i].pos * 100}%` }}
        >
          {bubble && bubble.agentId === agent.id && openId !== agent.id && (
            <div className="lilottie-bubble" role="status">
              {bubble.text}
            </div>
          )}

          {openId === agent.id && (
            <div className="lilottie-popover">
              <div className="lilottie-popover-bar">
                <span className="lilottie-dot lilottie-dot-r" />
                <span className="lilottie-dot lilottie-dot-y" />
                <span className="lilottie-dot lilottie-dot-g" />
                <span className="lilottie-popover-title">
                  {agent.name} · {agent.role}
                </span>
              </div>
              <div className="lilottie-popover-body">
                <p className="lilottie-line lilottie-line-cmd">{agent.cmd}</p>
                {agent.lines.map((line, li) => (
                  <p className="lilottie-line" key={li}>
                    {line}
                  </p>
                ))}
                <a
                  className="lilottie-popover-link"
                  href="/myspace"
                  style={{ color: agent.hueA }}
                  onClick={(e) => {
                    e.preventDefault();
                    history.push("/myspace");
                  }}
                >
                  meet all 9 live tools →
                </a>
              </div>
            </div>
          )}

          <button
            type="button"
            className="lilottie-hit"
            onClick={() => toggle(agent.id)}
            aria-label={`Chat with ${agent.name}, ${agent.role}`}
            aria-expanded={openId === agent.id}
          >
            <div
              className="lilottie-mount"
              ref={(el) => (mountRefs.current[i] = el)}
            />
          </button>
        </div>
      ))}
    </div>
  );
}

export default LilAgentsLottie;
