// Shared strolling behaviour for the hero companions, ported from
// lil-agents' WalkerCharacter (MIT): each agent independently picks a short
// walk, then rests, with the direction biased away from whichever edge it's
// near. Positions are normalised 0..1 across whatever strip the caller draws.
//
// NOTE: LilAgents3D and LilAgentsFlat still carry their own copies of this.
// Once a variant is chosen, point it at this module and delete the others.

export const DEFAULTS = {
  speed: 0.055, // track fractions per second
  minSep: 0.2, // closest two agents may stand
  pause: [4.5, 11], // seconds of rest between walks
  walkSpan: [0.14, 0.34], // fraction of the track covered per walk
  accel: 0.2,
  decel: 0.2,
  // Usable strip, inset so an agent never parks half outside the perch
  bounds: [0.06, 0.94],
};

export const clamp01 = (v) => Math.min(Math.max(v, 0), 1);
export const lerp = (a, b, t) => a + (b - a) * t;

// Integral of a trapezoidal velocity profile, normalised so t=1 -> distance 1.
// Driving position from this rather than a generic ease is what makes the
// start and stop read as a body with weight.
export const travelEase = (
  t,
  accel = DEFAULTS.accel,
  decel = DEFAULTS.decel
) => {
  const dLin = 1 - accel - decel;
  const v = 1 / (accel / 2 + dLin + decel / 2);
  if (t <= accel) return (v * t * t) / (2 * accel);
  if (t <= accel + dLin) return (v * accel) / 2 + v * (t - accel);
  const tt = t - accel - dLin;
  return (v * accel) / 2 + v * dLin + v * (tt - (tt * tt) / (2 * decel));
};

export function createWalkStates(count, opts = {}) {
  const { pause } = { ...DEFAULTS, ...opts };
  return Array.from({ length: count }, (_, i) => {
    const start = count === 1 ? 0.5 : 0.3 + (i * 0.4) / Math.max(count - 1, 1);
    return {
      pos: start,
      from: start,
      to: start,
      facing: i === 0 ? 1 : -1,
      dir: i === 0 ? 1 : -1,
      walking: false,
      // Stagger the first departure so they don't set off in lockstep
      pauseUntil: 1.5 + i * (pause[0] * 0.7),
      startedAt: 0,
      duration: 1,
      travelled: 0,
      moved: 0,
      gait: 0,
    };
  });
}

export function planWalk(self, peers, now, opts = {}) {
  const o = { ...DEFAULTS, ...opts };

  const [lo, hi] = o.bounds;
  const clampToTrack = (v) => Math.min(Math.max(v, lo), hi);

  // Turn away from an edge before actually reaching it
  const near = (hi - lo) * 0.18;
  if (self.pos > hi - near) self.dir = -1;
  else if (self.pos < lo + near) self.dir = 1;
  else self.dir = Math.random() < 0.5 ? -1 : 1;

  let to = clampToTrack(
    self.pos + self.dir * lerp(o.walkSpan[0], o.walkSpan[1], Math.random())
  );

  for (const other of peers) {
    if (other === self) continue;
    // Clamp against where the peer will END UP, not where it is now. Using its
    // current position lets two idle agents each legally target the same
    // midpoint and walk straight into one another.
    const peerTarget = other.walking ? other.to : other.pos;
    if (self.dir > 0 && peerTarget > self.pos)
      to = Math.min(to, peerTarget - o.minSep);
    else if (self.dir < 0 && peerTarget < self.pos)
      to = Math.max(to, peerTarget + o.minSep);
  }
  to = clampToTrack(to);

  // Boxed in — wait rather than jitter on the spot
  if (Math.abs(to - self.pos) < 0.02) {
    self.walking = false;
    self.pauseUntil = now + lerp(o.pause[0], o.pause[1], Math.random());
    return;
  }

  self.from = self.pos;
  self.to = to;
  self.duration = Math.max(0.8, Math.abs(to - self.pos) / o.speed);
  self.startedAt = now;
  self.walking = true;
  self.travelled = 0; // every walk starts on the same foot
  self.facing = to > self.pos ? 1 : -1;
}

// Advance one agent by a frame. `now` and `dt` are seconds.
export function stepWalk(self, peers, now, dt, opts = {}) {
  const o = { ...DEFAULTS, ...opts };

  if (self.frozenByUi) {
    self.walking = false;
    self.pauseUntil = now + 1.5;
    self.moved = 0;
  } else if (self.walking) {
    const t = clamp01((now - self.startedAt) / self.duration);
    const prev = self.pos;
    self.pos = lerp(self.from, self.to, travelEase(t, o.accel, o.decel));
    self.moved = Math.abs(self.pos - prev);
    self.travelled += self.moved;
    if (t >= 1) {
      self.walking = false;
      self.pauseUntil = now + lerp(o.pause[0], o.pause[1], Math.random());
    }
  } else {
    self.moved = 0;
    if (now >= self.pauseUntil) planWalk(self, peers, now, o);
  }

  // Per-frame ground speed, so anything keyed off it eases in and out with the
  // trapezoid instead of snapping at a threshold.
  const groundSpeed = dt > 0 ? self.moved / dt : 0;
  const target = self.walking ? Math.min(groundSpeed / (o.speed * 0.35), 1) : 0;
  self.gait = lerp(self.gait, target, 0.12);

  return { groundSpeed, amp: self.gait };
}
